package incident

import (
	"fmt"
	"strings"
	"time"

	"github.com/kafkamcp/kafkamcp/internal/randid"
)

// Hypothesis represents a root cause hypothesis generated by the AI responder.
type Hypothesis struct {
	ID          string   `json:"id"`
	Description string   `json:"description"`
	Confidence  float64  `json:"confidence"` // 0.0-1.0
	Component   string   `json:"component"`  // broker, consumer, producer, network, schema
	Evidence    []string `json:"evidence"`
	TestSteps   []string `json:"test_steps"` // steps to verify this hypothesis
}

// RemediationAction is a specific fix to apply.
type RemediationAction struct {
	ID               string         `json:"id"`
	Order            int            `json:"order"`
	Action           string         `json:"action"`
	Description      string         `json:"description"`
	Tool             string         `json:"tool,omitempty"` // MCP tool to invoke
	Params           map[string]any `json:"params,omitempty"`
	Risk             string         `json:"risk"` // low, medium, high
	Reversible       bool           `json:"reversible"`
	RequiresApproval bool           `json:"requires_approval"`
}

// RemediationRunbook is an auto-generated runbook for incident resolution.
type RemediationRunbook struct {
	ID          string              `json:"id"`
	IncidentID  string              `json:"incident_id"`
	Title       string              `json:"title"`
	Description string              `json:"description"`
	Hypotheses  []Hypothesis        `json:"hypotheses"`
	Actions     []RemediationAction `json:"actions"`
	Status      string              `json:"status"` // draft, pending_approval, approved, executing, completed, failed
	CreatedAt   string              `json:"created_at"`
	ApprovedBy  string              `json:"approved_by,omitempty"`
	ApprovedAt  string              `json:"approved_at,omitempty"`
}

// ApprovalGate represents a human-in-the-loop approval checkpoint.
type ApprovalGate struct {
	ID          string `json:"id"`
	RunbookID   string `json:"runbook_id"`
	ActionID    string `json:"action_id"`
	Status      string `json:"status"` // pending, approved, rejected
	Description string `json:"description"`
	RequestedAt string `json:"requested_at"`
	ReviewedBy  string `json:"reviewed_by,omitempty"`
	ReviewedAt  string `json:"reviewed_at,omitempty"`
	Notes       string `json:"notes,omitempty"`
}

// ExecutionLog tracks the execution of remediation actions.
type ExecutionLog struct {
	RunbookID string `json:"runbook_id"`
	ActionID  string `json:"action_id"`
	Status    string `json:"status"` // started, succeeded, failed, skipped
	Output    string `json:"output,omitempty"`
	Error     string `json:"error,omitempty"`
	StartedAt string `json:"started_at"`
	EndedAt   string `json:"ended_at,omitempty"`
}

// ResponderResult captures the full AI incident response output.
type ResponderResult struct {
	IncidentID  string              `json:"incident_id"`
	Hypotheses  []Hypothesis        `json:"hypotheses"`
	Runbook     *RemediationRunbook `json:"runbook"`
	Severity    string              `json:"severity"`
	Summary     string              `json:"summary"`
	GeneratedAt string              `json:"generated_at"`
}

// GenerateHypotheses creates root cause hypotheses from an incident's events.
func (c *Correlator) GenerateHypotheses(incidentID string) ([]Hypothesis, error) {
	c.mu.RLock()
	incident, ok := c.incidentMap[incidentID]
	c.mu.RUnlock()
	if !ok {
		return nil, fmt.Errorf("incident %q not found", incidentID)
	}

	var hypotheses []Hypothesis

	// Analyze event types to generate hypotheses
	eventTypes := make(map[string]int)
	for _, e := range incident.Events {
		eventTypes[e.Type]++
	}

	if eventTypes["broker_down"] > 0 {
		hypotheses = append(hypotheses, Hypothesis{
			ID:          randid.New("hyp"),
			Description: "Broker failure causing partition unavailability",
			Confidence:  0.85,
			Component:   "broker",
			Evidence:    []string{fmt.Sprintf("%d broker_down events detected", eventTypes["broker_down"])},
			TestSteps:   []string{"Check broker logs", "Verify broker connectivity", "Check disk space and memory"},
		})
	}

	if eventTypes["consumer_lag"] > 0 {
		confidence := 0.6
		if eventTypes["throughput_drop"] > 0 {
			confidence = 0.8
		}
		hypotheses = append(hypotheses, Hypothesis{
			ID:          randid.New("hyp"),
			Description: "Consumer processing bottleneck causing lag accumulation",
			Confidence:  confidence,
			Component:   "consumer",
			Evidence: []string{
				fmt.Sprintf("%d consumer_lag events", eventTypes["consumer_lag"]),
				fmt.Sprintf("Affected groups: %s", strings.Join(incident.Groups, ", ")),
			},
			TestSteps: []string{"Check consumer group status", "Analyze processing latency", "Check for rebalancing"},
		})
	}

	if eventTypes["throughput_drop"] > 0 && eventTypes["consumer_lag"] == 0 {
		hypotheses = append(hypotheses, Hypothesis{
			ID:          randid.New("hyp"),
			Description: "Producer-side issue causing throughput reduction",
			Confidence:  0.65,
			Component:   "producer",
			Evidence:    []string{fmt.Sprintf("%d throughput_drop events without consumer lag", eventTypes["throughput_drop"])},
			TestSteps:   []string{"Check producer connectivity", "Verify batch settings", "Check partition leader availability"},
		})
	}

	if eventTypes["error_spike"] > 0 {
		hypotheses = append(hypotheses, Hypothesis{
			ID:          randid.New("hyp"),
			Description: "Application error causing cascading failures",
			Confidence:  0.55,
			Component:   "producer",
			Evidence:    []string{fmt.Sprintf("%d error_spike events", eventTypes["error_spike"])},
			TestSteps:   []string{"Check application logs", "Verify schema compatibility", "Check serialization errors"},
		})
	}

	// If no specific hypothesis, generate a general one
	if len(hypotheses) == 0 {
		hypotheses = append(hypotheses, Hypothesis{
			ID:          randid.New("hyp"),
			Description: "Unknown anomaly requiring manual investigation",
			Confidence:  0.3,
			Component:   "unknown",
			Evidence:    []string{fmt.Sprintf("%d events across %d clusters", len(incident.Events), len(incident.Clusters))},
			TestSteps:   []string{"Review all cluster metrics", "Check network connectivity", "Review recent configuration changes"},
		})
	}

	return hypotheses, nil
}

// GenerateRunbook creates a remediation runbook for an incident.
func (c *Correlator) GenerateRunbook(incidentID string) (*RemediationRunbook, error) {
	hypotheses, err := c.GenerateHypotheses(incidentID)
	if err != nil {
		return nil, err
	}
	if len(hypotheses) == 0 {
		return nil, fmt.Errorf("no hypotheses generated for incident %q", incidentID)
	}

	c.mu.RLock()
	incident, ok := c.incidentMap[incidentID]
	c.mu.RUnlock()
	if !ok {
		return nil, fmt.Errorf("incident %q not found", incidentID)
	}

	runbook := &RemediationRunbook{
		ID:          randid.New("runbook"),
		IncidentID:  incidentID,
		Title:       fmt.Sprintf("Remediation: %s incident (%d events)", incident.Severity, len(incident.Events)),
		Description: fmt.Sprintf("Auto-generated runbook for incident %s affecting %s", incidentID, strings.Join(incident.Clusters, ", ")),
		Hypotheses:  hypotheses,
		Status:      "draft",
		CreatedAt:   time.Now().UTC().Format(time.RFC3339),
	}

	// Generate actions based on top hypothesis
	order := 1
	topHypothesis := hypotheses[0]

	// Diagnostic actions (always first, low risk)
	runbook.Actions = append(runbook.Actions, RemediationAction{
		ID:          fmt.Sprintf("action-%d", order),
		Order:       order,
		Action:      "diagnose",
		Description: "Gather cluster health metrics and broker status",
		Tool:        "kafka_cluster_info",
		Risk:        "low",
		Reversible:  true,
	})
	order++

	runbook.Actions = append(runbook.Actions, RemediationAction{
		ID:          fmt.Sprintf("action-%d", order),
		Order:       order,
		Action:      "diagnose",
		Description: "Check consumer group lag for affected groups",
		Tool:        "kafka_consumer_groups",
		Params:      map[string]any{"action": "lag"},
		Risk:        "low",
		Reversible:  true,
	})
	order++

	// Component-specific remediation
	switch topHypothesis.Component {
	case "broker":
		runbook.Actions = append(runbook.Actions, RemediationAction{
			ID:               fmt.Sprintf("action-%d", order),
			Order:            order,
			Action:           "remediate",
			Description:      "Trigger partition leader election for affected partitions",
			Tool:             "kafka_partition_reassign",
			Risk:             "medium",
			Reversible:       true,
			RequiresApproval: true,
		})
		order++

	case "consumer":
		for _, group := range incident.Groups {
			runbook.Actions = append(runbook.Actions, RemediationAction{
				ID:               fmt.Sprintf("action-%d", order),
				Order:            order,
				Action:           "remediate",
				Description:      fmt.Sprintf("Reset consumer group %s offsets to latest", group),
				Tool:             "kafka_reset_offsets",
				Params:           map[string]any{"group": group, "strategy": "latest"},
				Risk:             "high",
				Reversible:       false,
				RequiresApproval: true,
			})
			order++
		}

	case "producer":
		runbook.Actions = append(runbook.Actions, RemediationAction{
			ID:          fmt.Sprintf("action-%d", order),
			Order:       order,
			Action:      "diagnose",
			Description: "Analyze recent schema changes for compatibility issues",
			Tool:        "kafka_check_compatibility",
			Risk:        "low",
			Reversible:  true,
		})
		order++
	}

	// Verification action (always last)
	runbook.Actions = append(runbook.Actions, RemediationAction{
		ID:          fmt.Sprintf("action-%d", order),
		Order:       order,
		Action:      "verify",
		Description: "Verify incident is resolved by checking metrics",
		Tool:        "kafka_anomaly_detect",
		Risk:        "low",
		Reversible:  true,
	})

	c.mu.Lock()
	if c.runbooks == nil {
		c.runbooks = make(map[string]*RemediationRunbook)
	}
	c.runbooks[runbook.ID] = runbook
	c.mu.Unlock()

	return runbook, nil
}

// ApproveRunbook marks a runbook as approved for execution.
func (c *Correlator) ApproveRunbook(runbookID, approver string) (*RemediationRunbook, error) {
	c.mu.Lock()
	defer c.mu.Unlock()

	runbook, ok := c.runbooks[runbookID]
	if !ok {
		return nil, fmt.Errorf("runbook %q not found", runbookID)
	}
	if runbook.Status != "draft" && runbook.Status != "pending_approval" {
		return nil, fmt.Errorf("runbook %q is in status %q; must be draft or pending_approval", runbookID, runbook.Status)
	}

	runbook.Status = "approved"
	runbook.ApprovedBy = approver
	runbook.ApprovedAt = time.Now().UTC().Format(time.RFC3339)
	return runbook, nil
}

// ExecuteRunbook simulates executing an approved runbook.
func (c *Correlator) ExecuteRunbook(runbookID string) ([]ExecutionLog, error) {
	c.mu.Lock()
	defer c.mu.Unlock()

	runbook, ok := c.runbooks[runbookID]
	if !ok {
		return nil, fmt.Errorf("runbook %q not found", runbookID)
	}
	if runbook.Status != "approved" {
		return nil, fmt.Errorf("runbook %q must be approved before execution (status: %s)", runbookID, runbook.Status)
	}

	runbook.Status = "executing"
	var logs []ExecutionLog

	for _, action := range runbook.Actions {
		log := ExecutionLog{
			RunbookID: runbookID,
			ActionID:  action.ID,
			StartedAt: time.Now().UTC().Format(time.RFC3339),
		}

		// Simulate execution
		log.Status = "succeeded"
		log.Output = fmt.Sprintf("Executed %s: %s", action.Action, action.Description)
		log.EndedAt = time.Now().UTC().Format(time.RFC3339)

		logs = append(logs, log)
	}

	runbook.Status = "completed"
	return logs, nil
}

// GetRunbook returns a runbook by ID.
func (c *Correlator) GetRunbook(runbookID string) (*RemediationRunbook, error) {
	c.mu.RLock()
	defer c.mu.RUnlock()

	runbook, ok := c.runbooks[runbookID]
	if !ok {
		return nil, fmt.Errorf("runbook %q not found", runbookID)
	}
	return runbook, nil
}

// Respond performs full AI incident response: hypothesize, generate runbook.
func (c *Correlator) Respond(incidentID string) (*ResponderResult, error) {
	hypotheses, err := c.GenerateHypotheses(incidentID)
	if err != nil {
		return nil, err
	}

	runbook, err := c.GenerateRunbook(incidentID)
	if err != nil {
		return nil, err
	}

	c.mu.RLock()
	incident, ok := c.incidentMap[incidentID]
	c.mu.RUnlock()
	if !ok {
		return nil, fmt.Errorf("incident %q not found", incidentID)
	}

	summary := fmt.Sprintf("Incident with %d events across %d clusters.", len(incident.Events), len(incident.Clusters))
	if len(hypotheses) > 0 {
		summary += fmt.Sprintf(" Top hypothesis: %s (confidence: %.0f%%)", hypotheses[0].Description, hypotheses[0].Confidence*100)
	}

	return &ResponderResult{
		IncidentID:  incidentID,
		Hypotheses:  hypotheses,
		Runbook:     runbook,
		Severity:    string(incident.Severity),
		Summary:     summary,
		GeneratedAt: time.Now().UTC().Format(time.RFC3339),
	}, nil
}
